import {BY_ID,LESSONS} from './content.mjs';
import {learnedKana} from './engine.mjs';
import {visibleCells,visibleMonsters} from './dungeon-engine.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function dungeonHome(state){const d=state.dungeon,r=d.run,known=learnedKana(state).length,active=r?.status==='explore';return `<div class="page-heading"><div><h1>Подземелье хираганы</h1><p>Пошаговый roguelike · 3 этажа · около 5 минут</p></div></div><section class="surface progress-panel dungeon-intro"><div class="dungeon-sample" aria-hidden="true">░░░░░░░░░░░░<br>░<span>@</span> · · <b lang="ja">か</b> · · &gt;░<br>░░░ · ░░░░░░░</div><h2>Прочитай знак, чтобы атаковать</h2><p>Исследуй карту и победи по пять монстров на каждом этаже. Нажми на видимую хирагану и напиши чтение латиницей или по-русски. Верный ответ побеждает монстра и защищает от атак в этот ход.</p><p>Шесть единиц здоровья. Ошибка стоит одной. Зелье <strong>!</strong> лечит на две. Победи всех и найди лестницу <strong>&gt;</strong>. Время на ответ не ограничено.</p>${active?`<button class="primary wide" data-action="dungeon-resume">Продолжить · этаж ${r.floor} · ${r.hp}/6 здоровья</button>`:''}<form id="dungeon-start-form"><label for="dungeon-pool">Какие знаки повторять</label><select id="dungeon-pool" name="mode"><option value="learned" ${known?'':'disabled'}>${known?`Изученные · ${known} знаков`:'Изученные — сначала пройди урок'}</option>${LESSONS.map((l,i)=>`<option value="row:${l.id}" ${!known&&i===0?'selected':''}>${l.label} · ${l.ids.map(id=>BY_ID[id].char).join(' ')}</option>`).join('')}<option value="all">Все 46 знаков</option></select><button class="${active?'secondary':'primary'} wide" type="submit">${active?'Новый забег':'Начать забег'}</button></form><p class="tiny-note">В режиме «Изученные» неизвестных букв не будет. Ошибки и менее уверенные знаки встречаются чаще. Подсказка помогает пройти бой, но ответ с подсказкой не добавляет XP и не повышает уровень знания знака.</p></section>${d.history.length?`<section class="surface progress-panel"><h2>Последние забеги</h2>${d.history.slice(0,5).map(h=>`<p>${h.status==='won'?'Пройдено':'Поражение'} · этаж ${h.floor}/3 · ${h.kills} монстров · ${h.correct}/${h.answers} верных ответов · ${h.hints} подсказок</p>`).join('')}</section>`:''}`;}
export function dungeonRun(state,syncMarkup=''){
 const r=state.dungeon.run;if(!r)return '';const visible=visibleCells(r),monsters=visibleMonsters(r),target=r.monsters.find(m=>m.id===r.target),f=r.feedback,finished=r.status!=='explore';
 if(finished)return `<div class="dungeon-shell"><header class="dungeon-header"><button data-action="dungeon-exit" class="dungeon-back">← К режимам</button><span>ПОДЗЕМЕЛЬЕ</span></header><main id="main" class="dungeon-result"><span class="dungeon-result-mark">${r.status==='won'?'&gt;':'@'}</span><h1>${r.status==='won'?'Три этажа пройдены':'Забег завершён'}</h1><p>Этаж ${r.floor}/3 · побеждено ${r.kills} монстров</p><p>${r.correct} / ${r.answers} верных ответов · ${r.hints} подсказок</p><p>Ответы и ошибки сохранены в общем прогрессе.</p><div class="dungeon-result-errors">${r.retry.length?`Повтори: ${r.retry.map(id=>`<span lang="ja">${BY_ID[id].char}</span> ${esc(id)}`).join(' · ')}`:''}</div><button class="primary wide" data-action="dungeon-again">Новый забег</button><button class="dungeon-back" data-action="nav" data-view="practice">Повторить ошибки и знаки</button></main>${syncMarkup}</div>`;
 const cells=r.map.map((row,y)=>[...row].map((tile,x)=>{const i=y*15+x,lit=visible[i],seen=r.seen[i],m=lit?r.monsters.find(m=>m.x===x&&m.y===y):null,player=r.player.x===x&&r.player.y===y,exit=r.exit.x===x&&r.exit.y===y,potion=r.potion?.x===x&&r.potion?.y===y;
 if(m)return `<button class="dungeon-cell dungeon-monster ${r.target===m.id?'targeted':''}" data-action="dungeon-target" data-id="${m.id}" lang="ja" aria-label="Монстр ${BY_ID[m.kana].char}" ${f?'disabled':''}>${BY_ID[m.kana].char}</button>`;
 return `<span class="dungeon-cell ${!seen?'unseen':tile==='#'?'wall':player?'player':exit?'stairs':lit&&potion?'potion':'floor'} ${!lit&&seen?'remembered':''}" aria-hidden="true">${!seen?' ':player?'@':tile==='#'?'▓':exit?'&gt;':lit&&potion?'!':'·'}</span>`;}).join('')).join('');
 return `<div class="dungeon-shell"><header class="dungeon-header"><button data-action="dungeon-exit" class="dungeon-back" aria-label="Выйти из подземелья, сохранив забег">← Выйти</button><strong>Подземелье</strong><span>Этаж ${r.floor}/3</span></header><main id="main" class="dungeon-main"><div class="dungeon-status"><span class="dungeon-health" aria-label="Здоровье ${r.hp} из 6">♥ ${r.hp}/6</span><span>Побеждено ${5-r.monsters.length}/5</span><span>Ход ${r.turn}</span></div><div class="dungeon-layout"><section class="dungeon-map-panel"><div class="dungeon-map" role="group" aria-label="Карта подземелья. @ — ты, буквы — монстры, > — лестница, ! — зелье.">${cells}</div><div class="dungeon-map-legend"><span><b>@</b> ты</span><span><b lang="ja">あ</b> монстр</span><span><b>&gt;</b> лестница</span><span><b>!</b> +2 HP</span></div><div class="dungeon-controls" aria-label="Движение"><button data-action="dungeon-move" data-id="up" aria-label="Шаг вверх" ${f?'disabled':''}>↑</button><button data-action="dungeon-move" data-id="left" aria-label="Шаг влево" ${f?'disabled':''}>←</button><button data-action="dungeon-move" data-id="wait" aria-label="Ждать ход" ${f?'disabled':''}>·</button><button data-action="dungeon-move" data-id="right" aria-label="Шаг вправо" ${f?'disabled':''}>→</button><button data-action="dungeon-move" data-id="down" aria-label="Шаг вниз" ${f?'disabled':''}>↓</button></div><p class="dungeon-keys">Стрелки или кнопки · монстры ходят после тебя</p>${r.player.x===r.exit.x&&r.player.y===r.exit.y?`<button class="primary wide" data-action="dungeon-descend" ${f?'disabled':''}>${r.monsters.length?'Лестница: победи остальных':r.floor===3?'Выйти из подземелья':'Спуститься на этаж '+(r.floor+1)}</button>`:''}</section><section class="dungeon-battle" aria-label="Бой"><div class="dungeon-message" role="status">${esc(r.notice)}</div>${f?`<div class="dungeon-feedback ${f.kind}"><div class="dungeon-reading"><span lang="ja">${BY_ID[f.kana].char}</span><strong>${esc(f.kana)}</strong><small>примерно «${BY_ID[f.kana].ru}»</small></div><h2>${f.kind==='right'?f.earned?'Верно · +3 XP':'Монстр побеждён':f.kind==='hint'?'Чтение знака':'Ошибка · −1 здоровье'}</h2><p>${f.kind==='right'?'Следующий ход.':f.kind==='hint'?'После подсказки этот бой не повышает уровень знания знака.':'Прочитай знак ещё раз. На следующем этаже он встретится снова.'}</p><div class="dungeon-feedback-actions"><div class="dungeon-audio-pair"><button class="dungeon-back" data-action="play" data-id="${f.kana}">Послушать</button><button class="dungeon-back" data-action="play" data-id="${f.kana}" data-slow="true">Медленно</button></div><button class="primary" data-action="dungeon-next">Продолжить</button></div></div>`:`${monsters.length?`<p class="dungeon-target-label">Видимые монстры</p><div class="dungeon-targets">${monsters.map(m=>`<button class="${r.target===m.id?'selected':''}" data-action="dungeon-target" data-id="${m.id}" aria-label="Атаковать ${BY_ID[m.kana].char}" lang="ja">${BY_ID[m.kana].char}</button>`).join('')}</div>`:'<h2>Исследуй карту</h2><p>Иди к неоткрытой части карты. Монстры видны в освещённой области.</p>'}${target?`<form id="dungeon-answer-form"><label for="dungeon-reading">Прочитай <strong lang="ja">${BY_ID[target.kana].char}</strong></label><input id="dungeon-reading" name="reading" class="reading-input" placeholder="Чтение латиницей или по-русски" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="40" enterkeyhint="go" required><div class="dungeon-attack-actions"><button class="primary" type="submit">Атаковать</button><button class="dungeon-back" data-action="dungeon-hint" type="button">Подсказка</button></div></form>`:monsters.length?'<p>Выбери монстра на карте или над этим текстом.</p>':''}`}</section></div></main>${syncMarkup}</div>`;
}
